 if(/\bstop\b/i.test(content))icon='<path d="M65 34h40l27 26v40l-27 26H65L39 100V60Z" fill="#b84f48" stroke="white" stroke-width="5"/><text x="85" y="86" text-anchor="middle" font-size="21" fill="white" font-family="Helvetica Neue,Helvetica,Arial,sans-serif" font-weight="700">STOP</text>';
 else if(/ceda el paso/.test(content)) icon='<path d="M85 126L35 37h100Z" fill="white" stroke="#b44e47" stroke-width="9"/>';
